Theorem visit_uint64_root_ok : forall (v : Z) (LBo : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (sp r V S2 kx bx : Z) (g : eghost),
  g_es g = [] ->
  PMSA.cps_asan L ar HI PMESA.PC_VISIT_UINT64_xasan r sp (PMESA.VIS_SCRA 12800) (LBo ++ g_lbv g) FF LK cr A PMESA.VIS_D
    (fun R M => PMSA.a0 R V /\ (PMSA.a1 R v /\ 0 <= v < 2 ^ 64) /\ sp mod 32 = 0 /\ PMSA.stksh ar M sp (PMESA.VIS_SCRA 12800) /\ PMESA.enc_invA L IC EC M V S2 g /\ ev_guard (g_es g) EvU64 /\
                PMESA.eroomA CL g EvU64 /\ PMLA.img_ro IC M /\ PMESA.lits_ok L IC M /\ PMESA.ecreditA L CL cr g kx bx /\
                PMSA.fobj M FF V ENC_SIZE /\ PMSA.fobj M FF S2 24 /\ PMLA.apart V ENC_SIZE S2 24)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
